arguments.command:
cd /tmp/vally-eval-trial-Ktxizk && mkdir -p tests/CheckoutPricing.UnitTests/Checkout && 
cat > src/CheckoutPricing.Domain/CustomerTier.cs <<'E'
namespace CheckoutPricing.Domain;

public enum CustomerTier
{
    Standard,
    Gold
}
E
cat > src/CheckoutPricing.Application/CalculatePayableTotal.cs <<'E'
using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed class CalculatePayableTotal
{
    public decimal Handle(CustomerTier tier, decimal orderSubtotal) => orderSubtotal;
}
E
cat > tests/CheckoutPricing.IntegrationTests/GoldDiscountAcceptanceTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.IntegrationTests;

public sealed class GoldDiscountAcceptanceTests
{
    [Fact]
    public void S1_GoldCustomerReceivesTheApprovedDiscount()
    {
        var checkout = new CalculatePayableTotal();

        var payableTotal = checkout.Handle(CustomerTier.Gold, 100.00m);

        Assert.Equal(95.00m, payableTotal);
    }
}
E
rmdir tests/CheckoutPricing.UnitTests/Checkout
dotnet test tests/CheckoutPricing.IntegrationTests --verbosity quiet 2>&1 | grep -v "^$" | head -25

